#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <limits.h>

static int **parse_points(const char *s, int *rows_out, int **cols_out) {
    int capacity = 16;
    int rows = 0;
    int **points = (int **)malloc((size_t)capacity * sizeof(int *));
    int *cols = (int *)malloc((size_t)capacity * sizeof(int));

    if (!points || !cols) exit(EXIT_FAILURE);

    const char *p = s;
    while (*p) {
        while (*p && *p != '-' && !isdigit((unsigned char)*p))
            p++;

        if (!*p) break;

        char *end;
        long a = strtol(p, &end, 10);
        p = end;

        while (*p && *p != '-' && !isdigit((unsigned char)*p))
            p++;

        if (!*p) break;

        long b = strtol(p, &end, 10);
        p = end;

        if (rows == capacity) {
            capacity *= 2;
            points = (int **)realloc(points, (size_t)capacity * sizeof(int *));
            cols = (int *)realloc(cols, (size_t)capacity * sizeof(int));
            if (!points || !cols) exit(EXIT_FAILURE);
        }

        points[rows] = (int *)malloc(2 * sizeof(int));
        if (!points[rows]) exit(EXIT_FAILURE);

        points[rows][0] = (int)a;
        points[rows][1] = (int)b;
        cols[rows] = 2;
        rows++;
    }

    *rows_out = rows;
    *cols_out = cols;
    return points;
}

static int compare_points(const void *a, const void *b) {
    const int *pa = *(const int * const *)a;
    const int *pb = *(const int * const *)b;

    if (pa[1] < pb[1]) return -1;
    if (pa[1] > pb[1]) return 1;
    if (pa[0] < pb[0]) return -1;
    if (pa[0] > pb[0]) return 1;
    return 0;
}

int findMinArrowShots(int **points, int pointsSize, int *pointsColSize) {
    (void)pointsColSize;

    qsort(points, (size_t)pointsSize, sizeof(int *), compare_points);

    int arrows = 0;
    int lastArrow = 0;
    int hasArrow = 0;

    for (int i = 0; i < pointsSize; i++) {
        if (!hasArrow || points[i][0] > lastArrow) {
            arrows++;
            lastArrow = points[i][1];
            hasArrow = 1;
        }
    }

    return arrows;
}

