class Solution {
public:
    int findMinArrowShots(vector<vector<int>>& points) {
        sort(points.begin(), points.end(), [](const vector<int>& a, const vector<int>& b) {
            if (a[1] != b[1]) return a[1] < b[1];
            return a[0] < b[0];
        });

        int arrows = 0;
        int lastArrow = 0;
        bool hasArrow = false;

        for (const auto& p : points) {
            if (!hasArrow || p[0] > lastArrow) {
                ++arrows;
                lastArrow = p[1];
                hasArrow = true;
            }
        }

        return arrows;
    }
};

