        int arrows = 0;
        int lastArrow = 0;
        boolean hasArrow = false;

        for (int[] p : points) {
            if (!hasArrow || p[0] > lastArrow) {
                arrows++;
                lastArrow = p[1];
                hasArrow = true;
            }
        }

        return arrows;
    }
