static vector<string> splitTop(const string& s) {
    string t = s;
    while (!t.empty() && isspace(static_cast<unsigned char>(t.front()))) t.erase(t.begin());
    while (!t.empty() && isspace(static_cast<unsigned char>(t.back()))) t.pop_back();

    if (t == "[]") return {};

    t = t.substr(1, t.size() - 2);
    vector<string> parts;
    int depth = 0;
    size_t start = 0;

    for (size_t i = 0; i < t.size(); ++i) {
        char c = t[i];
        if (c == '[') ++depth;
        else if (c == ']') --depth;
        else if (c == ',' && depth == 0) {
            parts.push_back(t.substr(start, i - start));
            start = i + 1;
        }
    }

    parts.push_back(t.substr(start));
    return parts;
}

static vector<int> parseRow(const string& s) {
    vector<string> parts = splitTop(s);
    vector<int> row;

    for (const string& part : parts)
        row.push_back(stoi(part));

    return row;
}

static vector<vector<int>> parsePoints(const string& s) {
    vector<string> rows = splitTop(s);
    vector<vector<int>> points;

    for (const string& row : rows)
        points.push_back(parseRow(row));

    return points;
}

int main() {
    string line;
    getline(cin, line);

    string outer = line.substr(1, line.size() - 2);
    vector<vector<int>> points = parsePoints(outer);

    cout << Solution().findMinArrowShots(points) << '\n';
    return 0;
}

