    static String[] splitTop(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];

        s = s.substring(1, s.length() - 1);
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }

        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }

    static int[] parseRow(String s) {
        String[] parts = splitTop(s);
        int[] row = new int[parts.length];

        for (int i = 0; i < parts.length; i++) {
            row[i] = Integer.parseInt(parts[i].trim());
        }

        return row;
    }

    static int[][] parsePoints(String s) {
        String[] rows = splitTop(s);
        int[][] points = new int[rows.length][];

        for (int i = 0; i < rows.length; i++) {
            points[i] = parseRow(rows[i]);
        }

        return points;
    }

